def is_stable(rules, model):
    model = set(model)
    reduct = [(head, set(pos)) for head, pos, neg in rules if not set(neg) & model]
    derived = set()
    changed = True
    while changed:
        changed = False
        for head, pos in reduct:
            if head not in derived and pos <= derived:
                derived.add(head)
                changed = True
    return derived == model
